    private function audit(PDO $pdo,int $uid,string $action,int $loanId,string $note,?array $old=null,?array $new=null): void {
        $q=$pdo->prepare("INSERT INTO audit_logs(user_id,action,entity,entity_id,old_data,new_data,ip_address,user_agent) VALUES (?,?,'loans',?,?,?,?,?)");
        $q->execute([$uid,$action,$loanId,$old?json_encode($old,JSON_UNESCAPED_UNICODE):null,json_encode(array_merge($new??[],['notes'=>$note]),JSON_UNESCAPED_UNICODE),$_SERVER['REMOTE_ADDR']??null,$_SERVER['HTTP_USER_AGENT']??null]);
    }
    private function bulkAvailable(PDO $pdo,int $itemId,int $warehouseId): int {
        $q=$pdo->prepare("SELECT GREATEST(COALESCE(s.quantity,0)-COALESCE((
            SELECT SUM(li.quantity-li.returned_quantity) FROM loan_items li JOIN loans l ON l.id=li.loan_id
            WHERE li.master_item_id=? AND l.warehouse_id=? AND l.status IN ('BORROWED','PARTIAL_RETURNED') AND li.quantity>li.returned_quantity
        ),0)-COALESCE((
            SELECT SUM(lmi.quantity-lmi.returned_quantity) FROM loan_manual_items lmi JOIN loans lm ON lm.id=lmi.loan_id
            WHERE lmi.master_item_id=? AND lm.warehouse_id=? AND lm.status IN ('BORROWED','PARTIAL_RETURNED') AND lmi.quantity>lmi.returned_quantity
        ),0),0) FROM stocks s WHERE s.master_item_id=? AND s.warehouse_id=?");
        $q->execute([$itemId,$warehouseId,$itemId,$warehouseId,$itemId,$warehouseId]);
        return max(0,(int)$q->fetchColumn());
    }
    private function serialAvailable(PDO $pdo,int $itemId,int $warehouseId): int {
        $q=$pdo->prepare("SELECT COUNT(*) FROM serial_numbers WHERE master_item_id=? AND current_warehouse_id=? AND status='AVAILABLE'");$q->execute([$itemId,$warehouseId]);return (int)$q->fetchColumn();
    }
