        if(!AuthHelper::hasRole(['SUPERADMIN','ADMIN'])){$w[]='l.borrower_id=?';$p[]=(int)$u['id'];}
        if($search!==''){$w[]='(u.name LIKE ? OR w.name LIKE ?)';$p[]="%$search%";$p[]="%$search%";}
        if($status!==''){$w[]='l.status=?';$p[]=$status;}$where='WHERE '.implode(' AND ',$w);
        $c=$pdo->prepare("SELECT COUNT(*) FROM loans l JOIN users u ON u.id=l.borrower_id JOIN warehouses w ON w.id=l.warehouse_id $where");$c->execute($p);$totalItems=(int)$c->fetchColumn();$totalPages=max(1,(int)ceil($totalItems/$limit));
        $s=$pdo->prepare("SELECT l.*,u.name borrower_name,w.name warehouse_name FROM loans l JOIN users u ON u.id=l.borrower_id JOIN warehouses w ON w.id=l.warehouse_id $where ORDER BY l.id DESC LIMIT $limit OFFSET $offset");$s->execute($p);$loans=$s->fetchAll(PDO::FETCH_ASSOC);require __DIR__.'/../../resources/views/workflow/loans/index.php';
