            foreach($sources as $i=>$src){$qty=(int)($qtys[$i]??0);if($qty<1)continue;if($src==='MANUAL'){$name=trim($manual[$i]??'');if($name==='')throw new \Exception('Nama barang manual wajib diisi.');$mi->execute([$loanId,$name,$qty,trim($manualSpecs[$i]??''),trim($manualUnits[$i]??'')]);$lines++;continue;}$itemId=(int)($itemIds[$i]??0);$q=$pdo->prepare("SELECT id,nama,is_serialized FROM master_items WHERE id=? AND is_active=1");$q->execute([$itemId]);$item=$q->fetch(PDO::FETCH_ASSOC);if(!$item)throw new \Exception('Barang dari stok tidak valid.');$available=(int)$item['is_serialized']===1?$this->serialAvailable($pdo,$itemId,$wh):$this->bulkAvailable($pdo,$itemId,$wh);if($available<$qty)throw new \Exception("Barang {$item['nama']} yang tersedia untuk dipinjam hanya {$available}.");$si->execute([$loanId,$itemId,$qty]);$lines++;}
