    public function reject(): void {
        AuthHelper::requireRole(['ADMIN']);AuthHelper::denySuperadminWrite();$this->csrf('/loans');$pdo=Database::getInstance()->getConnection();$uid=(int)AuthHelper::user()['id'];$id=(int)($_POST['id']??0);$reason=trim($_POST['approval_notes']??'');if($reason===''){$_SESSION['error']='Alasan penolakan wajib diisi.';$this->go('/loans/show?id='.$id);}try{$pdo->beginTransaction();$q=$pdo->prepare("SELECT borrower_id,status FROM loans WHERE id=? FOR UPDATE");$q->execute([$id]);$loan=$q->fetch(PDO::FETCH_ASSOC);if(!$loan||$loan['status']!=='PENDING_APPROVAL')throw new \Exception('Peminjaman sudah diproses.');$pdo->prepare("UPDATE loans SET status='REJECTED',approved_by=?,approved_at=NOW(),approval_notes=?,processed_by=? WHERE id=?")->execute([$uid,$reason,$uid,$id]);$this->audit($pdo,$uid,'REJECT',$id,$reason,['status'=>'PENDING_APPROVAL'],['status'=>'REJECTED']);$pdo->commit();$_SESSION['success']='Peminjaman ditolak.';}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['error']='Gagal menolak: '.$e->getMessage();}$this->go('/loans/show?id='.$id);
