    public function handover(): void {
        AuthHelper::requireRole(['ADMIN']);AuthHelper::denySuperadminWrite();$this->csrf('/loans');$pdo=Database::getInstance()->getConnection();$svc=new StockService();$uid=(int)AuthHelper::user()['id'];$id=(int)($_POST['id']??0);
        try{$pdo->beginTransaction();$q=$pdo->prepare("SELECT * FROM loans WHERE id=? FOR UPDATE");$q->execute([$id]);$loan=$q->fetch(PDO::FETCH_ASSOC);if(!$loan||$loan['status']!=='APPROVED')throw new \Exception('Peminjaman belum siap diproses.');if(!empty($loan['outgoing_id']))throw new \Exception('Barang Keluar untuk peminjaman ini sudah dibuat.');$code=\App\Helpers\TransactionHelper::generateCode('OUT','outgoing');$pdo->prepare("INSERT INTO outgoing(transaction_code,warehouse_id,submission_id,purpose,loan_id,processed_by,notes,status) VALUES(?,?,NULL,'LOAN',?,?,?,'COMPLETED')")->execute([$code,$loan['warehouse_id'],$id,$uid,'Peminjaman '.$loan['transaction_code']]);$outId=(int)$pdo->lastInsertId();$outItem=$pdo->prepare("INSERT INTO outgoing_items(outgoing_id,master_item_id,submission_item_id,quantity) VALUES(?,?,NULL,?)");
            $q=$pdo->prepare("SELECT li.*,m.nama,m.is_serialized FROM loan_items li JOIN master_items m ON m.id=li.master_item_id WHERE li.loan_id=? AND li.quantity>0 ORDER BY li.id");$q->execute([$id]);foreach($q->fetchAll(PDO::FETCH_ASSOC) as $it){$qty=(int)$it['quantity'];$available=(int)$it['is_serialized']===1?$this->serialAvailable($pdo,(int)$it['master_item_id'],(int)$loan['warehouse_id']):$this->bulkAvailable($pdo,(int)$it['master_item_id'],(int)$loan['warehouse_id']);if($available<$qty)throw new \Exception("Stok {$it['nama']} berubah. Tersedia {$available}, akan dipinjam {$qty}.");$outItem->execute([$outId,$it['master_item_id'],$qty]);if((int)$it['is_serialized']===1){$sn=$pdo->prepare("SELECT serial_number_id FROM loan_item_serials WHERE loan_item_id=? AND status='PENDING' FOR UPDATE");$sn->execute([$it['id']]);$rows=$sn->fetchAll(PDO::FETCH_COLUMN);if(count($rows)!==$qty)throw new \Exception("Serial {$it['nama']} belum lengkap.");foreach($rows as $snId)$svc->moveSerial((int)$snId,'LOANED',null,null,(int)$loan['borrower_id'],'outgoing',$outId,'Barang Keluar Peminjaman '.$code);$pdo->prepare("UPDATE loan_item_serials SET status='BORROWED' WHERE loan_item_id=? AND status='PENDING'")->execute([$it['id']]);}}
            $q=$pdo->prepare("SELECT lmi.*,m.nama mapped_name,m.is_serialized FROM loan_manual_items lmi JOIN master_items m ON m.id=lmi.master_item_id WHERE lmi.loan_id=? AND lmi.quantity>0 ORDER BY lmi.id");$q->execute([$id]);foreach($q->fetchAll(PDO::FETCH_ASSOC) as $it){$qty=(int)$it['quantity'];$available=(int)$it['is_serialized']===1?$this->serialAvailable($pdo,(int)$it['master_item_id'],(int)$loan['warehouse_id']):$this->bulkAvailable($pdo,(int)$it['master_item_id'],(int)$loan['warehouse_id']);if($available<$qty)throw new \Exception("Stok {$it['mapped_name']} berubah. Tersedia {$available}, akan dipinjam {$qty}.");$outItem->execute([$outId,$it['master_item_id'],$qty]);if((int)$it['is_serialized']===1){$sn=$pdo->prepare("SELECT serial_number_id FROM loan_item_serials WHERE loan_manual_item_id=? AND status='PENDING' FOR UPDATE");$sn->execute([$it['id']]);$rows=$sn->fetchAll(PDO::FETCH_COLUMN);if(count($rows)!==$qty)throw new \Exception("Serial {$it['mapped_name']} belum lengkap.");foreach($rows as $snId)$svc->moveSerial((int)$snId,'LOANED',null,null,(int)$loan['borrower_id'],'outgoing',$outId,'Barang Keluar Peminjaman '.$code);$pdo->prepare("UPDATE loan_item_serials SET status='BORROWED' WHERE loan_manual_item_id=? AND status='PENDING'")->execute([$it['id']]);}}
            $pdo->prepare("UPDATE loans SET status='BORROWED',outgoing_id=?,handed_over_by=?,handed_over_at=NOW(),processed_by=? WHERE id=?")->execute([$outId,$uid,$uid,$id]);$this->audit($pdo,$uid,'HANDOVER',$id,'Peminjaman dieksekusi melalui Barang Keluar. Stok fisik tetap; availability berkurang karena custody.',['status'=>'APPROVED'],['status'=>'BORROWED','outgoing_id'=>$outId]);$pdo->commit();$_SESSION['success']='Barang Keluar peminjaman berhasil dibuat dan barang diserahkan.';
